#!/usr/bin/env node
'use strict';

/**
 * Markdown security regression suite.
 *
 * The renderer must treat every byte of author input as text. The only HTML
 * in the output is generated by the renderer itself. This suite enforces that
 * contract with:
 *   1. a corpus of known XSS payloads,
 *   2. a tag/attribute allowlist over every tag the renderer emits,
 *   3. a seeded fuzzer (1,000 cases) over obfuscated scheme and tag fragments.
 *
 * Run directly (`node tests/test-markdown-security.js`) or via tests/run-all.js.
 */

const assert = require('node:assert/strict');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const CodeLab = require(path.resolve(ROOT, 'dist/code-lab.js'));

if (typeof CodeLab.renderMarkdown !== 'function') {
  console.error('dist/code-lab.js does not export renderMarkdown. Run `bun run build` first.');
  process.exit(1);
}

const render = md => CodeLab.renderMarkdown(md);

// ── Output validators ───────────────────────────────────────────────────────

// Tags the renderer is allowed to emit. Anything else in the output came from
// the input and is a security bug.
const ALLOWED_TAGS = new Set([
  'a', 'blockquote', 'br', 'button', 'circle', 'code', 'del', 'div', 'em',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'hr', 'input', 'li', 'line', 'ol', 'p',
  'path', 'pre', 'rect', 'span', 'strong', 'svg', 'table', 'tbody', 'td',
  'th', 'thead', 'tr', 'ul'
]);

const ALLOWED_ATTRS = new Set([
  'aria-label', 'checked', 'class', 'cx', 'cy', 'd', 'data-cl-action',
  'data-cl-code', 'data-cl-task-idx', 'disabled', 'fill', 'height', 'href',
  'id', 'rel', 'role', 'r', 'rx', 'ry', 'stroke', 'stroke-width', 'style', 'tabindex',
  'target', 'title', 'type', 'viewbox', 'width', 'x', 'x1', 'x2', 'y', 'y1', 'y2'
]);

const DANGEROUS_SCHEME = /^(?:javascript|data|vbscript|file|blob):/i;

function normalizeForScheme(value) {
  return String(value).replace(/[\u0000-\u0020\u007F\u200B-\u200D\uFEFF]/g, '');
}

function extractTags(html) {
  const tags = [];
  const re = /<(\/?)([a-zA-Z][a-zA-Z0-9:-]*)((?:"[^"]*"|'[^']*'|[^>"'])*)>/g;
  let match;
  while ((match = re.exec(html)) !== null) {
    tags.push({ closing: match[1] === '/', name: match[2].toLowerCase(), attrs: match[3] || '' });
  }
  return tags;
}

function parseAttrs(attrString) {
  const attrs = [];
  const re = /([^\s"'=<>`/]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let match;
  while ((match = re.exec(attrString)) !== null) {
    attrs.push({
      name: match[1].toLowerCase(),
      value: match[2] !== undefined ? match[2] : (match[3] !== undefined ? match[3] : match[4])
    });
  }
  return attrs;
}

function validateHtml(html, context) {
  for (const tag of extractTags(html)) {
    assert.ok(
      ALLOWED_TAGS.has(tag.name),
      `${context}: unexpected <${tag.name}> tag in output\n${html}`
    );
    if (tag.closing) continue;

    for (const attr of parseAttrs(tag.attrs)) {
      assert.ok(
        ALLOWED_ATTRS.has(attr.name),
        `${context}: unexpected attribute "${attr.name}" on <${tag.name}>\n${html}`
      );

      if (attr.name === 'style') {
        assert.match(
          attr.value || '',
          /^text-align:(?:left|center|right);?$/,
          `${context}: unsafe style attribute "${attr.value}"\n${html}`
        );
      }

      if (attr.name === 'href') {
        const normalized = normalizeForScheme(attr.value || '');
        assert.ok(
          !DANGEROUS_SCHEME.test(normalized),
          `${context}: dangerous href "${attr.value}"\n${html}`
        );
      }

      // The renderer never emits src/formaction/xlink:href; those names are
      // already rejected by the allowlist. This is a second line of defence.
      if (attr.name === 'src' || attr.name === 'srcdoc' || attr.name === 'formaction') {
        assert.fail(`${context}: URL-bearing attribute "${attr.name}" is never generated\n${html}`);
      }
    }
  }

  // Event handlers and dangerous tags on real elements are covered by the tag
  // allowlist above. Event-handler-looking text is allowed to appear as visible
  // text (e.g. a README documenting `onerror=`), so do not grep raw output.
  assert.doesNotMatch(html, /<(?:script|iframe|object|embed|style|link|meta|base|form|math|template|noscript)\b/i,
    `${context}: dangerous raw tag in output\n${html}`);
}

// ── Tiny test harness ───────────────────────────────────────────────────────

let passed = 0;
const failures = [];

function test(name, fn) {
  try {
    fn();
    passed++;
  } catch (err) {
    failures.push({ name, err });
    console.error(`✘ ${name}`);
    console.error(`    ${err.message.split('\n')[0]}`);
  }
}

// ── Corpus: known payloads ──────────────────────────────────────────────────

const XSS_PAYLOADS = [
  '<script>alert(1)</script>',
  '<SCRIPT SRC=//evil.example/x.js></SCRIPT>',
  '<img src=x onerror=alert(1)>',
  '<img src="x" onerror="alert(1)">',
  '<svg onload=alert(1)>',
  '<svg/onload=alert(1)>',
  '<svg><script>alert(1)</script></svg>',
  '<iframe src="javascript:alert(1)"></iframe>',
  '<iframe srcdoc="<script>alert(1)</script>"></iframe>',
  '<object data="javascript:alert(1)"></object>',
  '<embed src="javascript:alert(1)">',
  '<math><mtext></mtext><script>alert(1)</script></math>',
  '<marquee onstart=alert(1)>x</marquee>',
  '<video><source onerror=alert(1)></video>',
  '<details open ontoggle=alert(1)>x</details>',
  '<body onload=alert(1)>',
  '<a href="javascript:alert(1)">click</a>',
  '<a href="JaVaScRiPt:alert(1)">click</a>',
  '<a href="java&#115;cript:alert(1)">click</a>',
  '<a href="&#106;avascript:alert(1)">click</a>',
  '<a href="data:text/html,<script>alert(1)</script>">click</a>',
  '<form action="javascript:alert(1)"><input type=submit></form>',
  '<base href="javascript:alert(1)//">',
  '<meta http-equiv="refresh" content="0;url=javascript:alert(1)">',
  '<link rel="stylesheet" href="javascript:alert(1)">',
  '<style>@import "javascript:alert(1)";</style>',
  '<!--<script>alert(1)</script>-->',
  '<template><script>alert(1)</script></template>',
  '<noscript><p title="</noscript><img src=x onerror=alert(1)>">',
  '<textarea></textarea><script>alert(1)</script>',
  '<title><script>alert(1)</script></title>',
  '<xss style="background:url(javascript:alert(1))">x</xss>',
  '<div onmouseover="alert(1)">x</div>',
  '" onmouseover="alert(1)',

  // Markdown link destinations
  '[click](javascript:alert(1))',
  '[click](JaVaScRiPt:alert(1))',
  '[click](java\tscript:alert(1))',
  '[click](java\nscript:alert(1))',
  '[click](java\u200Bscript:alert(1))',
  '[click](\u0001javascript:alert(1))',
  '[click](data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==)',
  '[click](vbscript:msgbox(1))',
  '[click](file:///etc/passwd)',
  '[click](blob:https://evil.example/abc)',
  '[click](ftp://evil.example/x)',

  // Link labels and image syntax
  '[<img src=x onerror=alert(1)>](https://example.com)',
  '[<script>alert(1)</script>](https://example.com)',
  '![x](javascript:alert(1))',
  '![<svg onload=alert(1)>](https://example.com)',

  // Autolinks
  '<https://example.com/\" onmouseover=\"alert(1)>',
  '<javascript:alert(1)>',
  '<data:text/html,<script>alert(1)</script>>',

  // Block-level injection
  '> <script>alert(1)</script>',
  '| a | b |\n| --- | --- |\n| <script>alert(1)</script> | x |',
  '- <img src=x onerror=alert(1)>',
  '1. <svg onload=alert(1)>',
  '> [!NOTE]\n> <iframe src=javascript:alert(1)>',

  // Placeholder forgery
  '\x00CODEBLOCK_0\x00',
  '\x00INLINECODE_0\x00',
  '\x00AUTOLINK_0\x00',
  '\x00LIST_0\x00'
];

for (const payload of XSS_PAYLOADS) {
  test(`payload: ${JSON.stringify(payload).slice(0, 70)}`, () => {
    const html = render(payload);
    validateHtml(html, 'payload');
    assert.doesNotMatch(html, /<script/i, 'raw <script> must never survive');
  });
}

// ── URL allowlist ───────────────────────────────────────────────────────────

const SAFE_URLS = [
  ['[x](https://example.com/a?b=c#d)', 'https://example.com/a?b=c#d'],
  ['[x](http://example.com)', 'http://example.com'],
  ['[x](mailto:security@example.com)', 'mailto:security@example.com'],
  ['[x](#section)', '#section'],
  ['[x](/absolute/path)', '/absolute/path'],
  ['[x](./relative/path.md)', './relative/path.md'],
  ['[x](../sibling/path.md)', '../sibling/path.md'],
  ['[x](//cdn.example.com/a.js)', '//cdn.example.com/a.js']
];

for (const [md, expectedHref] of SAFE_URLS) {
  test(`safe url preserved: ${expectedHref}`, () => {
    const html = render(md);
    assert.ok(html.includes(`href="${expectedHref.replace(/&/g, '&amp;')}"`), html);
    validateHtml(html, 'safe url');
  });
}

const BLOCKED_URLS = [
  'javascript:alert(1)',
  'JAVASCRIPT:alert(1)',
  'vbscript:msgbox(1)',
  'data:text/html,<script>alert(1)</script>',
  'file:///etc/passwd',
  'blob:https://example.com/abc',
  'ftp://example.com/x'
];

for (const url of BLOCKED_URLS) {
  test(`unsafe url neutralized: ${url.slice(0, 40)}`, () => {
    const html = render(`[x](${url.replace(/\s/g, '%20')})`);
    validateHtml(html, 'unsafe url');
    assert.ok(html.includes('href="#"'), `expected a dead link, got: ${html}`);
  });
}

// ── Benign markdown still renders ───────────────────────────────────────────

test('headings, emphasis, and code still render', () => {
  const html = render([
    '# Title',
    '',
    'Some **bold**, *italic*, ~~gone~~, and `inline`.',
    '',
    '```js',
    'const x = 1 < 2;',
    '```'
  ].join('\n'));

  assert.match(html, /<h2>Title<\/h2>/);
  assert.match(html, /<strong>bold<\/strong>/);
  assert.match(html, /<em>italic<\/em>/);
  assert.match(html, /<del>gone<\/del>/);
  assert.match(html, /<code class="codelab-inline-code">inline<\/code>/);
  assert.ok(html.includes('&lt;'));
  assert.doesNotMatch(html, /const x = 1 < 2;/);
  validateHtml(html, 'benign markdown');
});

test('raw HTML is shown as text, not parsed', () => {
  const html = render('<kbd>Ctrl</kbd> & <b>bold</b>');
  assert.ok(html.includes('&lt;kbd>Ctrl&lt;/kbd>'));
  assert.ok(!html.includes('<kbd>'));
  assert.ok(!html.includes('<b>'));
  validateHtml(html, 'raw html');
});

test('autolinks still render', () => {
  const html = render('See <https://example.com/docs> for details.');
  assert.ok(html.includes('href="https://example.com/docs"'));
  assert.ok(html.includes('>https://example.com/docs</a>'));
  validateHtml(html, 'autolink');
});

test('tables, callouts, task lists still render', () => {
  const html = render([
    '> [!WARNING]',
    '> Be careful',
    '',
    '| Name | Value |',
    '| :--- | ---: |',
    '| a | 1 |',
    '',
    '- [x] done',
    '- [ ] todo'
  ].join('\n'));

  assert.match(html, /codelab-callout--warning/);
  assert.match(html, /<table class="codelab-table">/);
  assert.match(html, /codelab-task-checkbox/);
  validateHtml(html, 'blocks');
});

test('code-lab custom elements cannot execute', () => {
  const html = render('<code-lab><script>alert(1)</script></code-lab>');
  assert.ok(!html.includes('<code-lab'));
  assert.ok(!html.includes('<script'));
  validateHtml(html, 'custom element');
});

// ── Seeded fuzzer ───────────────────────────────────────────────────────────

function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const FUZZ_TOKENS = [
  '<script>alert(1)</script>',
  '<img src=x onerror=alert(1)>',
  '<svg onload=alert(1)>',
  '<iframe src=javascript:alert(1)>',
  '<style>body{background:url(javascript:alert(1))}</style>',
  '<details open ontoggle=alert(1)>',
  '<a href="javascript:alert(1)">x</a>',
  '[x](javascript:alert(1))',
  '[x](JaVaScRiPt:alert(1))',
  '[x](java\nscript:alert(1))',
  '[x](java\tscript:alert(1))',
  '[x](java\u200Bscript:alert(1))',
  '[x](data:text/html;base64,PHNjcmlwdD4=)',
  '[x](vbscript:msgbox(1))',
  '[x](https://example.com)',
  '[x](#frag)',
  '[x](./rel.md)',
  '[<img src=x onerror=alert(1)>](https://example.com)',
  '<https://example.com>',
  '<javascript:alert(1)>',
  '# heading',
  '**bold**',
  '*italic*',
  '`inline <script>`',
  '```js\nconst x = 1 < 2;\n```',
  '> quote',
  '> [!NOTE]\n> note body',
  '| a | b |\n| --- | --- |\n| <b>x</b> | y |',
  '- item',
  '1. item',
  '- [x] task',
  '\x00CODEBLOCK_0\x00',
  '\x00AUTOLINK_0\x00',
  '" onmouseover="alert(1)',
  '&lt;script&gt;',
  '&#106;avascript:alert(1)',
  'plain text',
  'A & B',
  '<kbd>Ctrl</kbd>'
];

const FUZZ_SEPARATORS = ['', '\n', '\n\n', ' ', '\t'];

test('seeded fuzz: 1,000 payloads stay inert', () => {
  const random = mulberry32(0xc0ffee);
  for (let i = 0; i < 1000; i++) {
    const tokenCount = 1 + Math.floor(random() * 6);
    const parts = [];
    for (let j = 0; j < tokenCount; j++) {
      parts.push(FUZZ_TOKENS[Math.floor(random() * FUZZ_TOKENS.length)]);
    }
    const payload = parts.join(FUZZ_SEPARATORS[Math.floor(random() * FUZZ_SEPARATORS.length)]);
    const html = render(payload);
    try {
      validateHtml(html, `fuzz case ${i}`);
    } catch (err) {
      err.message += `\npayload: ${JSON.stringify(payload)}`;
      throw err;
    }
  }
});

// ── Results ─────────────────────────────────────────────────────────────────

console.log('');
console.log('='.repeat(62));
console.log(`Markdown security: ${passed} passed, ${failures.length} failed`);
console.log('='.repeat(62));

if (failures.length > 0) {
  for (const f of failures) {
    console.error(`\n[${f.name}]`);
    console.error(f.err.stack || f.err.message);
  }
  process.exitCode = 1;
} else {
  console.log('✅ Markdown renderer treats all input as text.');
}
